// Extract PDF links from legal documents categories
const categories = {
  'family': 'Code de la Famille',
  'labor': 'Code du Travail',
  'penal': 'Code Pénal',
  'commerce': 'Code de Commerce',
  'economy': 'Code Économique',
  'procedure': 'Code de Procédure Civile',
  'real_estate': 'Code de l\'Immobilier',
  'constitution': 'Constitution',
  'dahir': 'Dahirs',
  'marsoum': 'Maroums'
};

// Parse the HTML to extract document links
const documents = [];
for (const [key, name] of Object.entries(categories)) {
  documents.push({
    domain: key,
    name: name,
    url: `https://www.adala.ma/fr/${key}`,
    pdfLinks: []
  });
}

return documents;

// Extract PDF download links from category page
const html = $input.all()[0].body;
const pdfLinks = [];

// Parse HTML to find PDF links (adjust selector based on actual adala.ma structure)
const linkRegex = /href=["']([^"']*\.pdf)["']/gi;
let match;
while ((match = linkRegex.exec(html)) !== null) {
  pdfLinks.push({
    url: match[1],
    domain: $input.all()[0].domain,
    fileName: match[1].split('/').pop()
  });
}

return { domain: $input.all()[0].domain, pdfLinks: pdfLinks };

// Store PDF content for processing
// In production, use a PDF parsing library
return {
  fileName: $input.all()[0].fileName,
  domain: $input.all()[0].domain,
  fileSize: $input.all()[0].data?.length || 0,
  downloadedAt: new Date().toISOString()
};

// Extract articles from PDF content
// This is a simplified version - use pdfparse or similar library in production
const articles = [];

// Example structure for articles
const articlePattern = /Article\s+\d+[^\n]*/gi;

return {
  fileName: $input.all()[0].fileName,
  domain: $input.all()[0].domain,
  articlesCount: 0,
  articles: articles,
  extractedAt: new Date().toISOString()
};

// Create chunks from articles for processing
const chunkSize = 3; // Articles per chunk
const articles = $input.all()[0].articles || [];
const chunks = [];

for (let i = 0; i < articles.length; i += chunkSize) {
  chunks.push({
    chunkIndex: Math.floor(i / chunkSize),
    articles: articles.slice(i, i + chunkSize),
    domain: $input.all()[0].domain,
    fileName: $input.all()[0].fileName
  });
}

return { chunks: chunks, totalChunks: chunks.length };

// Parse Gemini response and format as JSONL
const rawString = $json.output || '';
const qaPairs = [];

try {
  // Find the start and end of the JSON content
  const jsonStartIndex = rawString.indexOf('{');
  const jsonEndIndex = rawString.lastIndexOf('}');

  if (jsonStartIndex !== -1 && jsonEndIndex !== -1) {
    const content = rawString.substring(jsonStartIndex, jsonEndIndex + 1);
    const lines = content.split('\n').filter(line => line.trim());

    lines.forEach((line) => {
      try {
        const jsonObj = JSON.parse(line);
        if (jsonObj.question && jsonObj.answer) {
          qaPairs.push(jsonObj);
        }
      } catch (e) {
        // Skip invalid JSON lines
      }
    });
  }
} catch (e) {
  // Error parsing response
}

return {
  domain: $input.all()[0].domain,
  fileName: $input.all()[0].fileName,
  chunkIndex: $input.all()[0].chunkIndex,
  qaPairs: qaPairs,
  pairsCount: qaPairs.length,
  processedAt: new Date().toISOString()
};

const fs = require('fs');
const path = require('path');

// Get data from input
const domain = $json.domain;
const qaPairs = $json.qaPairs || [];

// Define output directory (you can change this path)
const outputDir = '/tmp/legal_qa_output'; // Change to your desired path
const fileName = `${domain}.jsonl`;
const filePath = path.join(outputDir, fileName);

// Create directory if it doesn't exist
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Convert QA pairs to JSONL format
const jsonlContent = qaPairs.map(qa => JSON.stringify(qa)).join('\n') + '\n';

// Append to file
fs.appendFileSync(filePath, jsonlContent, 'utf8');

return {
  success: true,
  domain: domain,
  filePath: filePath,
  pairsWritten: qaPairs.length,
  message: `Successfully wrote ${qaPairs.length} Q&A pairs to ${fileName}`
};

// Generate summary and log completion status
return {
  status: 'completed',
  totalDocuments: $input.all().length,
  timestamp: new Date().toISOString(),
  message: 'Moroccan legal documents processing pipeline completed successfully'
};
